def is_unique_1(input_str):
    d = dict()           # 字典
    for i in input_str:
        if i in d:       # 如果i 已存在，则说明有重复字符，则返回True
            return False
        else:
            d[i] = 1     # 不存在，则设置d[i] = 1
    return True          # 循环结束 返回 True，说明所有字符都唯一

def is_unique_3(input_str):
    alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz "
    for i in input_str:
        if i in alpha:
            alpha = alpha.replace(i, "")
        else:
            return False
    return True
